    capsule('thigh',.13,.3,[0,-.2,0],darkConcrete,'body',leg);
    capsule('shin',.085,.27,[0,-.51,.035],skin,'body',leg);
    const boot=new THREE.Mesh(new THREE.BoxGeometry(.22,.14,.34),rubber);boot.position.set(0,-.73,.11);boot.castShadow=true;leg.add(boot);boot.userData.zone='body';
    const knee=new THREE.Mesh(new THREE.BoxGeometry(.2,.12,.08),mat(0x555548));knee.position.set(0,-.39,.12);leg.add(knee);knee.userData.zone='body';
